public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        String digits = Long.toString(n);
        int power = digits.length();
        long sum = 0, temp = n;
        while (temp > 0) {
            long d = temp % 10;
            sum += (long) Math.pow(d, power);
            temp /= 10;
        }
        System.out.println(sum == n ? "Armstrong" : "Not Armstrong");
    }
}

