import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long sum = 0;
        for (long d = 1; d * d <= n; d++) {
            if (n % d != 0) continue;
            sum += d;
            if (d != 1 && d != n / d) sum += n / d;
        }
        System.out.println(n > 1 && sum == n ? "Perfect" : "Not perfect");
    }
}

