        private final List<Observer> observers = new ArrayList<>();

        void register(Observer o) { observers.add(o); }

        void publish(int value) {
            for (Observer o : observers) o.update(value);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int value = sc.nextInt();
        Subject subject = new Subject();
        subject.register(v -> System.out.println("Observer A: " + v));
        subject.register(v -> System.out.println("Observer B: " + v));
        subject.publish(value);
    }
}

