        long tokens = capacity, last = -1;
        for (int i = 0; i < n; i++) {
            long now = sc.nextLong();
            if (last >= 0) tokens = Math.min(capacity, tokens + (now - last) * refill);
            last = now;
            if (tokens > 0) { tokens--; System.out.println("Allowed"); }
            else System.out.println("Denied");
        }
    }
}

