        void insert(String s) {
            Node cur = root;
            for (char c : s.toCharArray()) {
                int i = c - 'a';
                if (cur.child[i] == null) cur.child[i] = new Node();
                cur = cur.child[i];
            }
            cur.word = true;
        }

        boolean contains(String s) {
            Node cur = root;
            for (char c : s.toCharArray()) {
                cur = cur.child[c - 'a'];
                if (cur == null) return false;
            }
            return cur.word;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Trie trie = new Trie();
        int n = sc.nextInt();
        for (int i = 0; i < n; i++) trie.insert(sc.next());
        int q = sc.nextInt();
        for (int i = 0; i < q; i++) System.out.println(trie.contains(sc.next()) ? "YES" : "NO");
    }
}

