import java.util.*;

public class Main {
    static int count = 0;

    static void solve(int row, int n, boolean[] cols, boolean[] diag, boolean[] anti) {
        if (row == n) { count++; return; }
        for (int col = 0; col < n; col++) {
            int d = row - col + n, a = row + col;
            if (cols[col] || diag[d] || anti[a]) continue;
            cols[col] = diag[d] = anti[a] = true;
            solve(row + 1, n, cols, diag, anti);
            cols[col] = diag[d] = anti[a] = false;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        solve(0, n, new boolean[n], new boolean[2 * n], new boolean[2 * n]);
        System.out.println(count);
    }
}

