import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Map<String, Integer> stock = new TreeMap<>();
        while (sc.hasNext()) {
            String cmd = sc.next();
            if (cmd.equals("end")) break;
            if (cmd.equals("list")) {
                for (Map.Entry<String, Integer> e : stock.entrySet())
                    if (e.getValue() > 0) System.out.println(e.getKey() + "=" + e.getValue());
                continue;
            }
            String name = sc.next();
            int qty = sc.nextInt();
            stock.merge(name, cmd.equals("add") ? qty : -qty, Integer::sum);
        }
    }
}
